import{_ as e,o as d,c as a,a4 as o}from"./chunks/framework.DpieW3qv.js";const u=JSON.parse('{"title":"Wireframe Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/wireframe.md","filePath":"guides/wireframe.md","lastUpdated":null}'),r={name:"guides/wireframe.md"};function s(n,t,i,l,c,h){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="wireframe-guide" tabindex="-1">Wireframe Guide <a class="header-anchor" href="#wireframe-guide" aria-label="Permalink to &quot;Wireframe Guide&quot;">​</a></h1><blockquote><p>How to structure Excel/Smartsheet wireframes for the SFCC Campaign Automation system.</p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The wireframe is the <strong>source of truth</strong> for all campaign content. This guide explains the required format and structure.</p><hr><h2 id="supported-excel-formats" tabindex="-1">Supported Excel Formats <a class="header-anchor" href="#supported-excel-formats" aria-label="Permalink to &quot;Supported Excel Formats&quot;">​</a></h2><p>The system auto-detects the format based on column headers:</p><table tabindex="0"><thead><tr><th>Format</th><th>When to Use</th><th>Detection</th></tr></thead><tbody><tr><td><strong>CONVERTED</strong></td><td>Standard format (recommended)</td><td>Has REFRESH_NAME, REFRESH_DATE, ACTION, ASSET_TYPE, SITE_LOCATION</td></tr><tr><td><strong>BANNER</strong></td><td>Legacy LOFT format</td><td>Has WEB_PROD_CODED, DEVICE with date patterns</td></tr><tr><td><strong>FLAT_TIMED</strong></td><td>Timed refreshes</td><td>Has REFRESH_DATE, START_DATETIME, ACTION</td></tr></tbody></table><hr><h2 id="converted-format-recommended" tabindex="-1">CONVERTED Format (Recommended) <a class="header-anchor" href="#converted-format-recommended" aria-label="Permalink to &quot;CONVERTED Format (Recommended)&quot;">​</a></h2><h3 id="required-columns" tabindex="-1">Required Columns <a class="header-anchor" href="#required-columns" aria-label="Permalink to &quot;Required Columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>REFRESH NAME</code></td><td>Name of the refresh</td><td>&quot;1/26 Winter Sale&quot;</td></tr><tr><td><code>DATE</code> or <code>REFRESH DATE</code></td><td>When content goes live</td><td>1/26/2026</td></tr><tr><td><code>ACTION</code></td><td>What to do</td><td>LAUNCH, NO_CHANGE, REMOVE</td></tr><tr><td><code>SITE LOCATION</code></td><td>Where on site</td><td>HOMEPAGE, PPH, POPUP</td></tr><tr><td><code>ASSET TYPE</code></td><td>Content type</td><td>HOMEPAGE, PPH, COUPONS</td></tr></tbody></table><h3 id="optional-columns" tabindex="-1">Optional Columns <a class="header-anchor" href="#optional-columns" aria-label="Permalink to &quot;Optional Columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Aliases</th><th>Description</th></tr></thead><tbody><tr><td><code>ZONE</code></td><td>PLACEMENT, PLACEMENT ZONE</td><td>Specific zone within asset type</td></tr><tr><td><code>COPY</code></td><td>MESSAGE, COPY_MESSAGE, DISCLAIMER</td><td>Marketing copy text</td></tr><tr><td><code>DESTINATION ID</code></td><td>—</td><td>Link destination (category ID or URL)</td></tr><tr><td><code>IPID</code></td><td>—</td><td>Analytics tracking ID</td></tr><tr><td><code>ALT TEXT</code></td><td>—</td><td>Image accessibility text</td></tr><tr><td><code>TIME</code></td><td>START_TIME, TIME (ET)</td><td>Refresh time</td></tr><tr><td><code>ORDER</code></td><td>ITEM #, ITEM_ORDER</td><td>Item order within zone</td></tr><tr><td><code>NOTES</code></td><td>—</td><td>Internal notes</td></tr></tbody></table><h3 id="column-name-aliases" tabindex="-1">Column Name Aliases <a class="header-anchor" href="#column-name-aliases" aria-label="Permalink to &quot;Column Name Aliases&quot;">​</a></h3><p>The system accepts multiple column name variations:</p><table tabindex="0"><thead><tr><th>What You Can Use</th><th>Recognized As</th></tr></thead><tbody><tr><td><code>REFRESH NAME</code>, <code>PROJECT SUMMARY</code>, <code>INITIATIVE</code></td><td>REFRESH_NAME</td></tr><tr><td><code>DATE</code>, <code>REFRESH DATE</code>, <code>REFRESH_DATE</code></td><td>REFRESH_DATE</td></tr><tr><td><code>ACTION</code>, <code>LAUNCH/REMOVE</code>, <code>LAUNCH / REMOVE</code></td><td>ACTION</td></tr><tr><td><code>COPY</code>, <code>MESSAGE</code>, <code>PLACEMENT NOTES/PPH MESSAGE</code></td><td>COPY_MESSAGE</td></tr><tr><td><code>ZONE</code>, <code>PLACEMENT</code>, <code>PLACEMENT ZONE</code></td><td>ZONE</td></tr><tr><td><code>LINK/TRACKING</code>, <code>LINK</code>, <code>TRACKING</code></td><td>Link (parsed for destination)</td></tr></tbody></table><hr><h2 id="sheet-structure" tabindex="-1">Sheet Structure <a class="header-anchor" href="#sheet-structure" aria-label="Permalink to &quot;Sheet Structure&quot;">​</a></h2><h3 id="parent-child-rows" tabindex="-1">Parent-Child Rows <a class="header-anchor" href="#parent-child-rows" aria-label="Permalink to &quot;Parent-Child Rows&quot;">​</a></h3><p>The CONVERTED format uses parent-child row grouping:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ REFRESH NAME     │ DATE      │ ACTION │ ASSET TYPE │ ZONE     │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 1/26 Winter Sale │ 1/26/2026 │        │            │          │  ← Parent row</span></span>
<span class="line"><span>│                  │           │ LAUNCH │ HOMEPAGE   │ HP_HERO  │  ← Child row</span></span>
<span class="line"><span>│                  │           │ LAUNCH │ HOMEPAGE   │ HP_2T    │  ← Child row</span></span>
<span class="line"><span>│                  │           │ NO_CHANGE │ PPH     │ PPH      │  ← Child row</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 1/27 MLK Weekend │ 1/27/2026 │        │            │          │  ← Next parent</span></span>
<span class="line"><span>│                  │           │ LAUNCH │ HOMEPAGE   │ HP_HERO  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><strong>Parent Row</strong>: Has REFRESH NAME and DATE, no ASSET TYPE <strong>Child Rows</strong>: Have ACTION, ASSET TYPE, ZONE — inherit date from parent</p><hr><h2 id="action-types" tabindex="-1">Action Types <a class="header-anchor" href="#action-types" aria-label="Permalink to &quot;Action Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Meaning</th><th>System Behavior</th></tr></thead><tbody><tr><td><strong>LAUNCH</strong></td><td>New content</td><td>Generates new HTML, registers in asset registry</td></tr><tr><td><strong>NO_CHANGE</strong></td><td>Same as before</td><td>Reuses asset from registry, no new files</td></tr><tr><td><strong>REMOVE</strong></td><td>Delete content</td><td>Clears the slot</td></tr><tr><td><strong>UPDATE</strong></td><td>Data change only</td><td>Updates JSON, preserves existing HTML</td></tr></tbody></table><hr><h2 id="site-locations-zones" tabindex="-1">Site Locations &amp; Zones <a class="header-anchor" href="#site-locations-zones" aria-label="Permalink to &quot;Site Locations &amp; Zones&quot;">​</a></h2><h3 id="loft" tabindex="-1">LOFT <a class="header-anchor" href="#loft" aria-label="Permalink to &quot;LOFT&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Site Location</th><th>Asset Type</th><th>Zones</th><th>Notes</th></tr></thead><tbody><tr><td>HOMEPAGE</td><td>HOMEPAGE</td><td>HP_MOBILE_CATS, HP_PROMO_NAV, HP_TOP_BANNER, HP_HERO, HP_2T, HP_CAT_IMAGE, HP_DUO, HP_TRIO, HP_FEATURED_SHOPS, HP_SLOTS, HP_BOTTOM_BANNER, HP_RFLK_WIDGET, HP_UGC_WIDGET, HP_CHARITABLE_HUB_BAR, HP_LEFT_NAV_CONTENT_SLOT</td><td>15 canonical zones, composed in <code>&lt;div class=&quot;g3-hp&quot;&gt;</code></td></tr><tr><td>HP CAT NAV</td><td>→ consolidated to HOMEPAGE</td><td>HP_MOBILE_CATS</td><td>Auto-merged during parsing</td></tr><tr><td>CAT IMAGE</td><td>→ consolidated to HOMEPAGE</td><td>HP_CAT_IMAGE</td><td>Auto-merged during parsing</td></tr><tr><td>SLOT 1–4</td><td>→ consolidated to HOMEPAGE</td><td>HP_SLOTS</td><td>Auto-merged during parsing</td></tr><tr><td>BOTTOM BANNER</td><td>→ consolidated to HOMEPAGE</td><td>HP_BOTTOM_BANNER</td><td>Auto-merged during parsing</td></tr><tr><td>FEATURED SHOPS</td><td>→ consolidated to HOMEPAGE</td><td>HP_FEATURED_SHOPS</td><td>Auto-merged during parsing</td></tr><tr><td>RFLK/UGC WIDGET</td><td>→ consolidated to HOMEPAGE</td><td>HP_RFLK/UGC_WIDGET</td><td>Auto-merged during parsing</td></tr><tr><td>PPH</td><td>PPH</td><td>PPH (single zone)</td><td></td></tr><tr><td>POPUP</td><td>POPUP</td><td>POPUP (single zone)</td><td></td></tr><tr><td>COUPONS</td><td>COUPONS</td><td>COUPONS (single zone)</td><td></td></tr><tr><td>PLP HEADER</td><td>PLP_HEADER</td><td>By category</td><td></td></tr><tr><td>FP</td><td>FP, FP DENIM, FP PANTS</td><td>By type (plp-callout)</td><td></td></tr><tr><td>NFP</td><td>NFP, NFP PP</td><td>By type (plp-callout)</td><td></td></tr></tbody></table><h3 id="ann-taylor" tabindex="-1">Ann Taylor <a class="header-anchor" href="#ann-taylor" aria-label="Permalink to &quot;Ann Taylor&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Site Location</th><th>Asset Type</th><th>Zones</th></tr></thead><tbody><tr><td>HP MAIN</td><td>HP MAIN</td><td>HP MAIN (single zone)</td></tr><tr><td>TOP BANNER</td><td>TOP BANNER (ABOVE MAIN)</td><td>Single zone</td></tr><tr><td>BOTTOM BANNER</td><td>BOTTOM BANNER (BELOW MAIN)</td><td>Single zone</td></tr><tr><td>PPH</td><td>PPH (SLOT 1-5)</td><td>PPH (SLOT 1), PPH (SLOT 2), etc.</td></tr><tr><td>POPUP</td><td>DISCLAIMER POP UP</td><td>Single zone</td></tr><tr><td>COUPONS</td><td>COUPON PAGE CAT151000X</td><td>By category ID</td></tr><tr><td>PLP</td><td>*PLP HEADER, *PLP BANNER</td><td>SALE PLP HEADER, etc.</td></tr></tbody></table><hr><h2 id="ipid-format" tabindex="-1">IPID Format <a class="header-anchor" href="#ipid-format" aria-label="Permalink to &quot;IPID Format&quot;">​</a></h2><p>IPIDs (Internal Promotion IDs) are used for analytics tracking.</p><h3 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h3><p>This structure is the canonical definition. The system builds every IPID from exactly these eight segments, in order:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{brand}_{page}_{device}_{zone}_{position}_{promo}_{destination}_{date}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="segment-reference-canonical" tabindex="-1">Segment reference (canonical) <a class="header-anchor" href="#segment-reference-canonical" aria-label="Permalink to &quot;Segment reference (canonical)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Segment</th><th>Placeholder</th><th>Description</th><th>Example values</th></tr></thead><tbody><tr><td>1. Brand</td><td><code>{brand}</code></td><td>Brand key (no cross-brand)</td><td><code>loft</code>, <code>at</code></td></tr><tr><td>2. Page</td><td><code>{page}</code></td><td>Page / asset type</td><td><code>hp</code>, <code>pph</code>, <code>popup</code>, <code>plp</code></td></tr><tr><td>3. Device</td><td><code>{device}</code></td><td>Device / audience</td><td><code>all</code>, <code>mobile</code>, <code>desktop</code></td></tr><tr><td>4. Zone</td><td><code>{zone}</code></td><td>Zone within the page</td><td><code>hero1ta1</code>, <code>main</code>, <code>hp-2t</code></td></tr><tr><td>5. Position</td><td><code>{position}</code></td><td>Item position in zone (1-based)</td><td><code>1</code>, <code>2</code>, <code>a</code></td></tr><tr><td>6. Promo</td><td><code>{promo}</code></td><td>Promo/copy slug or <code>np</code></td><td><code>sale50</code>, <code>30offsuiting</code>, <code>np</code></td></tr><tr><td>7. Destination</td><td><code>{destination}</code></td><td>Destination slug</td><td><code>saleviewall</code>, <code>suits</code>, <code>na</code></td></tr><tr><td>8. Date</td><td><code>{date}</code></td><td><strong>MMDDYY</strong> (6 digits only)</td><td><code>012626</code>, <code>012026</code></td></tr></tbody></table><ul><li><strong>Date segment:</strong> Exactly <strong>MMDDYY</strong> (6 digits). No other date format is used for IPIDs.</li><li><strong>Brand segment:</strong> <code>loft</code> or <code>at</code> only. <strong>No cross-brand use:</strong> LOFT assets must use only <code>loft_</code> IPIDs; Ann Taylor assets must use only <code>at_</code> IPIDs.</li></ul><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><table tabindex="0"><thead><tr><th>IPID</th><th>Breakdown</th></tr></thead><tbody><tr><td><code>loft_hp_all_hero1ta1_sale50_saleviewall_012626</code></td><td>LOFT, homepage, all audiences, hero zone, 50% sale, Jan 26 (MMDDYY: 012626)</td></tr><tr><td><code>at_pph_all_pph_1_30offsuiting_suits_012026</code></td><td>Ann Taylor, PPH, all, 30% off suiting, Jan 20 2026 (MMDDYY: 012026)</td></tr></tbody></table><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ul><li>Lowercase only</li><li>Underscores as separators</li><li><strong>Date at end: MMDDYY only (6 digits)</strong></li><li><strong>No cross-brand:</strong> Use the correct brand prefix for the current run</li><li>Be consistent across refreshes</li></ul><hr><h2 id="destination-types" tabindex="-1">Destination Types <a class="header-anchor" href="#destination-types" aria-label="Permalink to &quot;Destination Types&quot;">​</a></h2><p>The system infers destination type from the value:</p><table tabindex="0"><thead><tr><th>Value Pattern</th><th>Inferred Type</th></tr></thead><tbody><tr><td><code>https://...</code></td><td>URL</td></tr><tr><td><code>CAT123456</code>, <code>CATA...</code></td><td>CATEGORY</td></tr><tr><td><code>/path/to/page</code></td><td>URL</td></tr><tr><td>Other</td><td>PRODUCT</td></tr></tbody></table><hr><h2 id="multiple-refreshes-per-day" tabindex="-1">Multiple Refreshes Per Day <a class="header-anchor" href="#multiple-refreshes-per-day" aria-label="Permalink to &quot;Multiple Refreshes Per Day&quot;">​</a></h2><p>If you have multiple refreshes on the same day:</p><ol><li>Include time in the refresh name: &quot;1/26 3AM Site Changeout&quot;</li><li>The system assigns ordinals automatically: r1, r2, r3...</li><li>Use the TIME column for precise scheduling</li></ol><hr><h2 id="multiple-sheets" tabindex="-1">Multiple Sheets <a class="header-anchor" href="#multiple-sheets" aria-label="Permalink to &quot;Multiple Sheets&quot;">​</a></h2><p>The system scans all sheets in the workbook and uses the first one that matches a known format.</p><p><strong>Priority order</strong>: CONVERTED &gt; BANNER &gt; FLAT_TIMED</p><p>To force a specific sheet, run: <code>make excel ARGS=&quot;--sheet=&#39;Sheet Name&#39;&quot;</code></p><hr><h2 id="validation-checklist" tabindex="-1">Validation Checklist <a class="header-anchor" href="#validation-checklist" aria-label="Permalink to &quot;Validation Checklist&quot;">​</a></h2><p>Before saving your wireframe:</p><ul><li>[ ] All required columns present (REFRESH NAME, DATE, ACTION, ASSET TYPE, SITE LOCATION)</li><li>[ ] Actions are valid (LAUNCH, NO_CHANGE, REMOVE)</li><li>[ ] Dates are in M/D/YYYY format</li><li>[ ] No empty rows breaking parent-child grouping</li><li>[ ] IPIDs follow naming convention</li><li>[ ] Zones match expected values for each asset type</li></ul><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="issue-rows-not-parsing" tabindex="-1">Issue: Rows not parsing <a class="header-anchor" href="#issue-rows-not-parsing" aria-label="Permalink to &quot;Issue: Rows not parsing&quot;">​</a></h3><p><strong>Check:</strong></p><ul><li>Is there a parent row with REFRESH NAME and DATE?</li><li>Are required columns present?</li><li>Are there merged cells breaking the structure?</li></ul><h3 id="issue-wrong-asset-type" tabindex="-1">Issue: Wrong asset type <a class="header-anchor" href="#issue-wrong-asset-type" aria-label="Permalink to &quot;Issue: Wrong asset type&quot;">​</a></h3><p><strong>Check:</strong></p><ul><li>Is ASSET TYPE spelled correctly?</li><li>Is SITE LOCATION filled in?</li><li>Does the zone name match expected patterns?</li></ul><h3 id="issue-dates-not-recognized" tabindex="-1">Issue: Dates not recognized <a class="header-anchor" href="#issue-dates-not-recognized" aria-label="Permalink to &quot;Issue: Dates not recognized&quot;">​</a></h3><p><strong>Check:</strong></p><ul><li>Use M/D/YYYY format (1/26/2026)</li><li>Avoid text formatting on date cells</li><li>Check Excel is interpreting as date, not text</li></ul><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a> — How to run commands</li><li><a href="/ocapi-docs.github.io/guides/templates.html">Template Guide</a> — How to edit HTML templates</li><li><a href="/ocapi-docs.github.io/reference/commands.html">Commands Reference</a> — All make commands</li></ul>`,77)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
